public abstract class METCustomerMDFCalculation
{
    CustAccount custAccount;
    InventSiteId siteId;
    SalesInventLocationId locationId;
    ItemId itemId;

}

Method.Source:
Query updateQuery(Query _query)
{
    QueryBuildDataSource  qbdsCustomerMDFTable = _query.dataSourceTable(tableNum(MetCustomerMdfTable));

    qbdsCustomerMDFTable.addRange(fieldNum(MetCustomerMdfTable, CustAccount)).value(custAccount);
    qbdsCustomerMDFTable.addRange(fieldNum(MetCustomerMdfTable, InventSiteId)).value(siteId);
    qbdsCustomerMDFTable.addRange(fieldNum(MetCustomerMdfTable, InventLocationId)).value(locationId);

    return _query;
}

void process()
{
    Query query = this.getQuery();
    query = this.updateQuery(query);

    QueryRun queryRun = new QueryRun(query);

    while(queryRun.next())
    {
        MetCustomerMdfSetupTable customerMdfSetupTable = queryRun.get(tableNum(MetCustomerMdfSetupTable));

        if(this.shouldProcessItem(customerMdfSetupTable, itemId))
        {

        }
    }
}

boolean shouldProcessItem(MetCustomerMdfSetupTable _customerMdfSetupTable, ItemId _itemId)
{
    boolean ret = true;

    switch(_customerMdfSetupTable.ItemScope)
    {
        case METItemScope::AllItems:
            ret = true;
            break;
        case METItemScope::ExplicitItemInclusion:
            ret = this.isItemExplicitlyIncluded(_customerMdfSetupTable, _itemId);
            break;
        case METItemScope::ItemsWithExclusions:
            ret = !this.isItemExcluded(_customerMdfSetupTable, _itemId);
            break;
    }

    return ret;
}

public CustAccount parmCustAccount(CustAccount _custAccount = custAccount)
{
    custAccount = _custAccount;

    return custAccount;
}

public InventSiteId parmInventSiteId(InventSiteId _siteId = siteId)
